  let common : List (Int × Int) := [(2, -16), (2, -12), (2, -9)]
  let rest : List (Int × Int) :=
    if turn < 0 then [(3, -7), (5, -5), (7, -3), (8, -2), (9, -2), (12, -2), (15, -2)]
    else if turn > 0 then [(1, -6), (0, -2), (-2, 1), (-5, 2), (-8, 2), (-12, 2), (-15, 2)]
    else [(2, -6), (2, -3), (2, 0), (2, 3), (2, 7), (2, 12), (2, 15)]
  let p := (common ++ rest).getD k (0, 0)
  (m p.1, m p.2)

def headingAt (turn : Int) (k : Nat) : Vec :=
  if k ≤ 4 || turn == 0 then Build.north else if turn < 0 then Build.east else Build.west

